<?php
$u=sr_auth('recruiter');$jobId=max(0,(int)($_GET['job_id']??0));$stage=(string)($_GET['stage']??'');
$jobs=sr_all('SELECT id,title FROM jobs WHERE recruiter_id=? ORDER BY id DESC',[$u['id']]);
$where=['j.recruiter_id=?'];$args=[$u['id']];
if($jobId){$where[]='a.job_id=?';$args[]=$jobId;}
if(in_array($stage,['submitted','reviewing','shortlisted','rejected'],true)){$where[]='a.status=?';$args[]=$stage;}
$apps=sr_all('SELECT a.*,j.title,j.company,u.name,u.email,cp.headline,cp.location FROM applications a JOIN jobs j ON j.id=a.job_id JOIN users u ON u.id=a.candidate_id LEFT JOIN candidate_profiles cp ON cp.user_id=a.candidate_id WHERE '.implode(' AND ',$where).' ORDER BY (a.score IS NULL) ASC,a.score DESC,a.created_at DESC',$args);
sr_page_heading('TALENT PIPELINE','Quản lý ứng viên','Theo dõi các hồ sơ ứng tuyển theo vị trí và trạng thái xử lý.');
?><div class="panel filter-inline"><form method="get" class="filter-row"><input type="hidden" name="page" value="applicants"><label>Vị trí tuyển dụng<select name="job_id"><option value="0">Tất cả vị trí</option><?php foreach($jobs as $j):?><option value="<?=$j['id']?>" <?=$jobId===(int)$j['id']?'selected':''?>><?=h($j['title'])?></option><?php endforeach;?></select></label><label>Trạng thái<select name="stage"><option value="">Tất cả</option><?php foreach(['submitted','reviewing','shortlisted','rejected'] as $v):?><option value="<?=$v?>" <?=$stage===$v?'selected':''?>><?=h(sr_status($v))?></option><?php endforeach;?></select></label><button class="button primary">Lọc ứng viên</button></form></div>
<div class="toolbar"><span><strong><?=count($apps)?></strong> hồ sơ ứng tuyển</span><small class="muted">Sắp xếp theo điểm AI cao đến thấp (nếu có)</small></div>
<?php if(!$apps):?><div class="panel empty-state"><h2>Chưa có ứng viên phù hợp bộ lọc</h2><p>Các hồ sơ ứng tuyển sẽ xuất hiện tại đây.</p><a class="button secondary" href="<?=sr_url('myjobs')?>">Xem tin tuyển dụng</a></div><?php else:?><div class="panel table-panel"><div class="table-responsive"><table><thead><tr><th>Ứng viên</th><th>Ứng tuyển vị trí</th><th>Điểm AI</th><th>Trạng thái</th><th>Hồ sơ</th></tr></thead><tbody><?php foreach($apps as $a):?><tr><td><strong><?=h($a['name'])?></strong><small><?=h($a['headline']?:$a['email'])?></small></td><td><?=h($a['title'])?></td><td><?php if($a['score']!==null):?><strong class="score-pill"><?=number_format((float)$a['score'],0)?>%</strong><?php else:?><span class="muted">Chưa đánh giá</span><?php endif;?></td><td><span class="badge <?=sr_state_class($a['status'])?>"><?=h(sr_status($a['status']))?></span></td><td><a class="button secondary xs" href="<?=sr_url('applicant',['id'=>$a['id']])?>">Xem chi tiết →</a></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?><div class="privacy-note">Điểm AI chỉ giúp hỗ trợ sắp xếp và tham khảo. Nhà tuyển dụng cần đánh giá toàn diện và công bằng khi quyết định.</div>
